export function vorbisTimestampFixture(absolute = false): File {
	return new File([Uint8Array.from(Buffer.from(absolute ? ABSOLUTE : ZERO, 'base64'))],
		absolute ? 'Broadcast.ogg' : 'Ordinary.ogg', { type: 'audio/ogg' });
}

export function vorbisTimestampReference(): readonly Float32Array[] {
	const bytes = inflateSync(Buffer.from(REFERENCE, 'base64'));
	return Array.from({ length: 2 }, (_, channel) => Float32Array.from({ length: 4800 }, (_, frame) => bytes.readFloatLE((frame * 2 + channel) * 4)));
}
